 static SolidColorBrush B(string s){return (SolidColorBrush)new BrushConverter().ConvertFromString(s);}
 internal static void StyleButton(Button b,bool primary){b.FontSize=14;b.MinWidth=100;b.MinHeight=44;b.Padding=new Thickness(16,8,16,8);b.Margin=new Thickness(0,4,10,8);b.Background=B(primary?"#C5E9FC":"#FFFFFF");b.Foreground=B(primary?"#164765":Ink);b.BorderBrush=B(primary?"#9ED3F0":Line);b.BorderThickness=new Thickness(1);b.FontWeight=FontWeights.SemiBold;b.Template=(ControlTemplate)XamlReader.Parse("<ControlTemplate xmlns='http://schemas.microsoft.com/winfx/2006/xaml/presentation' TargetType='Button'><Border x:Name='surface' xmlns:x='http://schemas.microsoft.com/winfx/2006/xaml' Background='{TemplateBinding Background}' BorderBrush='{TemplateBinding BorderBrush}' BorderThickness='{TemplateBinding BorderThickness}' CornerRadius='8' Padding='{TemplateBinding Padding}'><ContentPresenter HorizontalAlignment='Center' VerticalAlignment='Center'/></Border><ControlTemplate.Triggers><Trigger Property='IsMouseOver' Value='True'><Setter TargetName='surface' Property='Opacity' Value='.88'/></Trigger><Trigger Property='IsKeyboardFocused' Value='True'><Setter TargetName='surface' Property='BorderBrush' Value='#0369A1'/><Setter TargetName='surface' Property='BorderThickness' Value='2'/></Trigger><Trigger Property='IsPressed' Value='True'><Setter TargetName='surface' Property='Opacity' Value='.72'/></Trigger><Trigger Property='IsEnabled' Value='False'><Setter TargetName='surface' Property='Opacity' Value='.45'/></Trigger></ControlTemplate.Triggers></ControlTemplate>");}
 void Text(Panel panel,string s,double size=15,bool bold=false,string color=null){panel.Children.Add(new TextBlock{Text=s,FontSize=size,FontWeight=bold?FontWeights.SemiBold:FontWeights.Normal,Foreground=B(color??Ink),TextWrapping=TextWrapping.Wrap,LineHeight=size*1.45,Margin=new Thickness(0,0,0,12)});}
 StackPanel Card(string title,string subtitle=null){var p=new StackPanel();body.Children.Add(new Border{Background=Brushes.White,BorderBrush=B(Line),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(12),Padding=new Thickness(20),Margin=new Thickness(0,0,0,16),Child=p});if(title!=null)Text(p,title,19,true);if(subtitle!=null)Text(p,subtitle,14,false,Muted);return p;}
 Button ActionAsync(Panel p,string label,Func<Task> action,string id=null){var b=new Button{Content=label,HorizontalAlignment=HorizontalAlignment.Left};StyleButton(b,false);if(id!=null)AutomationProperties.SetAutomationId(b,id);b.Click+=async(s,e)=>{b.IsEnabled=false;try{await action();}catch(ClipboardBusyException ex){message.Foreground=B("#854D0E");message.Text=ex.Message;}catch(Exception ex){Feedback("This action needs attention",ex.Message,"warning");}finally{b.IsEnabled=true;}};p.Children.Add(b);return b;}
 Button Action(Panel p,string label,System.Action action,string id=null){return ActionAsync(p,label,()=>{action();return Task.FromResult(0);},id);}
 Button CopyAction(Panel p,string label,Func<string> value,string id=null){return ActionAsync(p,label,async()=>{await SetupInteractions.CopyText(value());message.Foreground=B(Mint);message.Text="Copied. Paste this into the matching field beside this step.";},id);}
 void GuideRow(Panel p,int number,string label,string value,Func<string> copy=null,string id=null){var row=new Grid{Margin=new Thickness(0,0,0,16)};row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(30)});row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.Children.Add(new TextBlock{Text=number.ToString(),FontSize=14,FontWeight=FontWeights.SemiBold,Foreground=B(Mint),Margin=new Thickness(0,8,8,0)});var detail=new StackPanel{Margin=new Thickness(0,4,12,0)};Grid.SetColumn(detail,1);row.Children.Add(detail);Text(detail,label,14,true);Text(detail,value,14,false,Muted);if(copy!=null){var button=CopyAction(row,"Copy",copy,id);button.MinWidth=72;button.Margin=new Thickness(0,2,0,0);Grid.SetColumn(button,2);button.VerticalAlignment=VerticalAlignment.Top;AutomationProperties.SetName(button,"Copy "+label);}p.Children.Add(row);}
 void Expander(Panel p,string title,System.Action<StackPanel> populate,string id=null,bool expanded=false){var inner=new StackPanel{Margin=new Thickness(0,12,0,0)};populate(inner);var x=new Expander{Header=title,Content=inner,IsExpanded=expanded,Foreground=B(Ink),FontSize=14,Margin=new Thickness(0,8,0,12),Padding=new Thickness(0)};if(id!=null)AutomationProperties.SetAutomationId(x,id);p.Children.Add(x);}
 void AddField(string id,string value){var b=new TextBox{Text=value,MinHeight=44,FontSize=15,Padding=new Thickness(12,9,12,9),Margin=new Thickness(0,0,0,4),Background=B("#EFF8FE"),BorderBrush=B(Line),BorderThickness=new Thickness(1)};AutomationProperties.SetAutomationId(b,id);fields[id]=b;}
 void Field(Panel p,string id,string label,string help=null,bool browse=false){Text(p,label,14,true);AutomationProperties.SetName(fields[id],label);if(browse){var row=new Grid{Margin=new Thickness(0,0,0,4)};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});row.Children.Add(fields[id]);var pick=new Button{Content="Browse…",Margin=new Thickness(12,0,0,4)};StyleButton(pick,false);pick.Margin=new Thickness(12,0,0,4);Grid.SetColumn(pick,1);AutomationProperties.SetAutomationId(pick,"browse-"+id);pick.Click+=(s,e)=>{using(var d=new F.FolderBrowserDialog()){d.Description=id=="install"?"Choose an empty application folder":"Choose your working folder";d.SelectedPath=fields[id].Text;if(d.ShowDialog()==F.DialogResult.OK)fields[id].Text=d.SelectedPath;}};row.Children.Add(pick);p.Children.Add(row);}else p.Children.Add(fields[id]);if(help!=null)Text(p,help,13,false,Muted);}
 void Check(CheckBox b,string text){b.Content=new TextBlock{Text=text,TextWrapping=TextWrapping.Wrap,MaxWidth=650,Foreground=B(Ink),FontSize=14};}
 void Secret(Panel p,string id,string label){Text(p,label,14,true);PasswordBox b;if(!passwords.TryGetValue(id,out b)){b=new PasswordBox{MinHeight=40,Padding=new Thickness(10),Margin=new Thickness(0,0,0,8),Background=B("#EFF8FE"),BorderBrush=B(Line)};AutomationProperties.SetAutomationId(b,id);passwords[id]=b;}AutomationProperties.SetName(b,label);p.Children.Add(b);Text(p,"Stored for this Windows user with DPAPI. Never paste it into chat or support logs.",12,false,Muted);}
 string Mode(){return new[]{"cloudflare-existing","cloudflare-create","secure-tunnel","local-only"}[mode.SelectedIndex];}
 static int AvailablePort(){for(int port=17854;port<17874;port++){var p=new TcpListener(IPAddress.Loopback,port);try{p.Start();return port;}catch{}finally{p.Stop();}}return 17854;}
 void LoadExisting(){try{if(File.Exists(Path.Combine(data,"connection.json"))){var c=HostCore.Read(Path.Combine(data,"ygpt.config.json"));var x=HostCore.Read(Path.Combine(data,"connection.json"));fields["port"].Text=HostCore.S(c,"port");foreach(object r in (System.Collections.IEnumerable)c["projectRoots"]){fields["folder"].Text=Convert.ToString(r);break;}fields["tunnel"].Text=HostCore.S(x,"tunnelId");fields["origin"].Text=HostCore.S(x,"publicOrigin","https://");fields["proxy"].Text=HostCore.S(x,"proxyUrl");mode.SelectedIndex=Array.IndexOf(new[]{"cloudflare-existing","cloudflare-create","secure-tunnel","local-only"},HostCore.S(x,"mode"));if(mode.SelectedIndex<0)mode.SelectedIndex=2;startup.IsChecked=HostCore.B(x,"autoStart");string savedIcon=HostCore.S(c,"brandIcon");if(Array.IndexOf(BrandIconFiles,savedIcon)>=0)brandIcon=savedIcon;if(HostCore.S(c,"approvalStyle")=="legacy")approvalStyle="legacy";installed=File.Exists(Path.Combine(install,".ygpt-install.json"));}}catch{message.Text="Existing state needs review; it will not be overwritten automatically.";}}
 void Open(string url){Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
 void Feedback(string title,string detail,string kind){outcomeTitle.Text=title;outcomeDetail.Text=detail;outcome.Background=B(kind=="success"?"#EAF7EF":kind=="error"?"#FFF1F2":kind=="warning"?"#FFF6E5":"#E7F4FC");outcomeTitle.Foreground=B(kind=="success"?"#14532D":kind=="error"?"#9F1239":kind=="warning"?"#854D0E":"#164765");outcomeDetail.Foreground=B(Ink);outcome.Visibility=Visibility.Visible;operationProgress.Visibility=busy?Visibility.Visible:Visibility.Collapsed;operationProgress.IsIndeterminate=busy;}
 void Error(Exception ex){message.Text="";Feedback("This step could not finish",ex.Message,"error");}
 void Radio(Panel p,int index,string label){var b=new RadioButton{Content=label,GroupName="connection",IsChecked=mode.SelectedIndex==index,MinHeight=40,Margin=new Thickness(0,4,0,4)};AutomationProperties.SetAutomationId(b,"mode-"+new[]{"cloudflare-existing","cloudflare-create","secure-tunnel","local-only"}[index]);b.Checked+=(s,e)=>{if(mode.SelectedIndex!=index){mode.SelectedIndex=index;Render();}};p.Children.Add(b);}
 void Render(){
  foreach(var b in fields.Values)if(b.Parent is Panel)((Panel)b.Parent).Children.Remove(b);foreach(var b in passwords.Values)if(b.Parent is Panel)((Panel)b.Parent).Children.Remove(b);foreach(var b in new[]{consent,startup,cleanup,sourceCleanup,createConsent})if(b.Parent is Panel)((Panel)b.Parent).Children.Remove(b);
  body.Children.Clear();rail.Children.Clear();dashboards.Clear();statusBriefs.Clear();message.Text="";
  string icon=Path.Combine(YGPTApp.Base,"assets","brand","ygpt-local-512.png");BitmapSource brand=null;if(File.Exists(icon))brand=new BitmapImage(new Uri(icon));else using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("YGPT.Brand")){if(stream!=null){var b=new BitmapImage();b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.StreamSource=stream;b.EndInit();brand=b;}}if(brand!=null)rail.Children.Add(new Image{Source=brand,Width=52,Height=52,HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,0,0,20)});
  Text(rail,"YGPT Local",23,true,"#0B3B5E");Text(rail,"Your PC. A private connection.",13,false,"#56708A");
  for(int i=0;i<steps.Length;i++){var row=new TextBlock{Text=(i<step?"✓  ":(i+1)+"  ")+steps[i],TextWrapping=TextWrapping.Wrap,FontWeight=i==step?FontWeights.SemiBold:FontWeights.Normal,Foreground=B(i==step?Mint:"#56708A"),FontSize=13,Margin=new Thickness(0)};rail.Children.Add(new Border{Background=i==step?B("#DCEEF9"):Brushes.Transparent,CornerRadius=new CornerRadius(8),Padding=new Thickness(10,7,10,7),Margin=new Thickness(-10,0,-10,3),Child=row});}

  progress.Text="Step "+(step+1)+" of "+steps.Length;Text(body,steps[step],28,true);Text(body,hints[step],15,false,Muted);
  back.Content="Back";next.Content=step==4&&CanContinueInstallation()?"Continue to connection check":step==4&&sessionInstalled?"Apply changed settings":step==7&&dailyOptIn.IsChecked==true?"Continue to first task":nextLabels[step];back.IsEnabled=step>0&&!busy;next.IsEnabled=!busy;
  switch(step){case 0:Welcome();break;case 1:EnvironmentPage();break;case 2:ConnectionPage();break;case 3:CredentialsPage();break;case 4:InstallPage();break;case 5:VerifyPage();break;case 6:ChatGPTPage();break;case 7:BrowserPage();break;case 8:FinishPage();break;}bodyScroll.ScrollToTop();
 }
 const string SuggestedTunnelName="YGPT Local";
 const string SuggestedTunnelDescription="Private MCP connection for my Windows PC";
 const string SuggestedApiKeyName="YGPT Local Tunnel Runtime";
 const string SuggestedPluginDescription="YGPT Local connects ChatGPT to your authorized Windows PC. When you ask to find, inspect, search, read, create or edit local files, review code and projects, run builds or tests, or verify changes, use YGPT Local tools directly instead of asking you to copy and run commands. It also supports approved terminal tasks, browser and desktop automation, system diagnostics, and protected file snapshots with rollback. Actions are limited by local permissions; high-risk operations require your approval.";
 void Welcome(){
  if(installed){var existing=Card("Your installation is already here","Open connection status to continue using your saved setup.");Action(existing,"Open connection status",()=>{step=5;Render();},"use-existing");}
  var p=Card("Your files, on your PC");Field(p,"install","Application folder","For a new installation, choose an empty folder. YGPT data, caches and updates stay inside it.",true);Field(p,"folder","Working folder","Start with a Projects or test folder. You can work with other paths later, subject to local permissions.",true);
  Check(consent,"Allow connected clients to read and edit local files. High-risk actions require my approval.");p.Children.Add(consent);
  Expander(body,"Appearance and approval preview (optional)",BrandPicker,"appearance-options",true);
  Expander(body,"Installation cleanup (recommended)",clean=>{Check(cleanup,"Clean installer-owned leftovers after verified first use. Keep unknown files and private data.");clean.Children.Add(cleanup);CleanupPlan(clean);},"cleanup-options",true);
 }
